object Solution {
    def mergeTwoLists(list1: ListNode, list2: ListNode): ListNode = {
        val head = new ListNode()
        var tail = head
        var (ptr1, ptr2) = (list1, list2)

        while (ptr1 != null && ptr2 != null) {
            if (ptr1.x <= ptr2.x) {
                tail.next = ptr1
                ptr1 = ptr1.next
            } else {
                tail.next = ptr2
                ptr2 = ptr2.next
            }

            tail = tail.next
        }

        if (ptr1 != null) {
            tail.next = ptr1
        } else if (ptr2 != null) {
            tail.next = ptr2
        }

        return head.next
    }
}

object Solution {
    def search(nums: Array[Int], target: Int): Int = {
        var (left, right) = (0, nums.length - 1)

        while (left <= right) {
            val mid = (left + right) / 2

            if (target == nums(mid)) {
                return mid
            } else if (nums(mid) >= nums(left)) {
                if (target >= nums(left) && target < nums(mid)) {
                    right = mid - 1
                } else {
                    left = mid + 1
                }
            } else {
                if (target > nums(mid) && target <= nums(right)) {
                    left = mid + 1
                } else {
                    right = mid - 1
                }
            }
        }

        return -1
    }
}

object Solution {
  def isValidSudoku(board: Array[Array[Char]]): Boolean = {
    import scala.collection.mutable.{Set => MSet}
    val rowSet = MSet[(Int, Char)]()
    val colSet = MSet[(Int, Char)]()
    val squareSet = MSet[(Int, Int, Char)]()

    val indices = for {
      i <- (0 to 8).toList
      j <- (0 to 8).toList
    } yield (i, j)

    indices
      .map { case (i, j) =>
        (i, j, board(i)(j))
      }
      .filter(_._3 != '.')
      .forall { case (i, j, char) =>
        if(
            rowSet.contains((i, char))
          | colSet.contains((j, char))
          | squareSet.contains((i / 3, j / 3, char))
        ) false
        else {
          rowSet += ((i, char))
          colSet += ((j, char))
          squareSet += ((i / 3, j / 3, char))
          true
        }
      }
  }
}

