        traverse(word) match {
            case Some(endNode) => endNode.isEndOfWord
            case None => false
        }
    }

    def startsWith(prefix: String): Boolean = {
        traverse(prefix).isDefined
    }

    private def traverse(word: String): Option[TrieNode] = {
        var curr = root
        for (c <- word) {
            if (!curr.children.contains(c)) {
                return None
            } else {
                curr = curr.children(c)
            }
        }

        return Some(curr)
    }
}

