/**
 * Definition for a binary tree node.
 * class TreeNode(_value: Int = 0, _left: TreeNode = null, _right: TreeNode = null) {
 *   var value: Int = _value
 *   var left: TreeNode = _left
 *   var right: TreeNode = _right
 * }
 */
object Solution {
    def isSubtree(root: TreeNode, subRoot: TreeNode): Boolean = {
        if (root == null && subRoot == null) {
            return true
        } else if (root != null && subRoot == null) {
            return true
        } else if (root == null && subRoot != null) {
            return false
        } else {
            return isSameTree(root, subRoot) || (isSubtree(root.left, subRoot) || isSubtree(root.right, subRoot))
        }
    }

    def isSameTree(p: TreeNode, q: TreeNode): Boolean = {
        if (p == null && q == null) {
            return true
        } else if (p == null || q == null) {
            return false
        } else if (p.value != q.value) {
            return false
        } else {
            return isSameTree(p.left, q.left) && isSameTree(p.right, q.right)
        }
    }
}

object Solution {
    def checkPossibility(nums: Array[Int]): Boolean = {
        @scala.annotation.tailrec
        def helper(i: Int = 1, mismatch: Int = 0, last: Int = nums.head): Boolean =
            if (i == nums.length) true
            else if (nums(i) >= last) helper(i + 1, mismatch, nums(i))
            else if (mismatch > 0) false
            else if (i == nums.length - 1) true
            else if (nums(i - 1) <= nums(i + 1)) helper(i + 1, mismatch + 1, nums(i))
            else if (i == 1 && nums(i) <= nums(i + 1)) helper(i + 1, mismatch + 1, nums(i))
            else if (i > 1 && nums(i - 2) <= nums(i)) helper(i + 1, mismatch + 1, nums(i))
            else false

        helper()
  }
}

object Solution {
  def search(nums: Array[Int], target: Int): Int = {
    var left = 0
    var right = nums.length - 1

    while (left <= right) {
      val mid = left + (right - left) / 2

      if (nums(mid) == target) {
        return mid
      } else if (nums(mid) < target) {
        left = mid + 1
      } else {
        right = mid - 1
      }
    }

    return -1
  }
}

object Solution {
    def minCostClimbingStairs(cost: Array[Int]): Int = {
        val n = cost.length
        var first = cost(0)
        var second = cost(1)
        if (n<=2)
            first min second
        else {
            for ( i <- 2 until n) {
                val curr = cost(i) + (first min second)
                first = second
                second = curr
            }
            first min second
        }
    }
}

object Solution {
    def getConcatenation(nums: Array[Int]): Array[Int] = {
        val n = nums.length
        val ans = new Array[Int](2 * n)

        for (i <- 0 until n) {
            ans(i) = nums(i)
            ans(i + n) = nums(i)
        }

        ans
    }
}
